{
  "name": "opencode-sonar-fix",
  "version": "0.1.0",
  "description": "OpenCode plugin + slash command that fetches NEW SonarQube issues introduced by the current PR and lets the agent fix them automatically.",
  "keywords": [
    "opencode",
    "opencode-plugin",
    "sonarqube",
    "sonar",
    "code-quality",
    "static-analysis",
    "github",
    "pull-request"
  ],
  "license": "MIT",
  "author": "Md Azaz Ali <azazali30@gmail.com>",
  "homepage": "https://github.com/azazali30/opencode-sonar-fix#readme",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/azazali30/opencode-sonar-fix.git"
  },
  "bugs": {
    "url": "https://github.com/azazali30/opencode-sonar-fix/issues"
  },
  "type": "module",
  "main": "./dist/index.js",
  "types": "./dist/index.d.ts",
  "exports": {
    ".": {
      "types": "./dist/index.d.ts",
      "import": "./dist/index.js"
    },
    "./commands/sonar-fix.md": "./commands/sonar-fix.md",
    "./package.json": "./package.json"
  },
  "files": [
    "dist",
    "commands",
    "examples",
    "README.md",
    "LICENSE"
  ],
  "scripts": {
    "build": "tsc -p tsconfig.json",
    "clean": "rm -rf dist",
    "prepublishOnly": "npm run clean && npm run build",
    "typecheck": "tsc -p tsconfig.json --noEmit"
  },
  "peerDependencies": {
    "@opencode-ai/plugin": ">=1.0.0"
  },
  "devDependencies": {
    "@opencode-ai/plugin": "^1.4.3",
    "@types/node": "^22.0.0",
    "typescript": "^5.5.0"
  },
  "engines": {
    "node": ">=18"
  },
  "publishConfig": {
    "access": "public"
  }
}
